/**
 * Enumeration of the possible button interaction states
 *
 * @author John Blanco
 */
import '../../../globals.js';
import Enumeration from '../../../phet-core/js/Enumeration.js';
import EnumerationValue from '../../../phet-core/js/EnumerationValue.js';
import sun from '../sun.js';
class ButtonInteractionState extends EnumerationValue {
}
// button is just sitting there, doing nothing
ButtonInteractionState.IDLE = new ButtonInteractionState();
// a pointer is over the button, but it is not being pressed
ButtonInteractionState.OVER = new ButtonInteractionState();
// the button is being pressed by the user
ButtonInteractionState.PRESSED = new ButtonInteractionState();
ButtonInteractionState.enumeration = new Enumeration(ButtonInteractionState);
export default ButtonInteractionState;
sun.register('ButtonInteractionState', ButtonInteractionState);
